export const LEGACY_IMPORT_RECEIPT_KINDS: ReadonlySet<string> = new Set<ImportReceipt['kind']>(['create', 'edit', 'analyze', 'adopt', 'decisions', 'cancel-analysis', 'cancel-publication', 'upload', 'publish', 'cleanup', 'select-cover']);
